scripts.script:
import java.nio.file.*

def srcDir = new File(project.build.directory, 'generated-sources/refactoring')

// 1. shortenUtils.kt: allowAnalysisFromWriteActionInEdt is removed in analysis-api 2.3.21;
//    replace with plain analyze {} which works in write actions under our session model.
def shortenFile = new File(srcDir, 'org/jetbrains/kotlin/idea/base/analysis/api/utils/shortenUtils.kt')
if (shortenFile.exists()) {
  def text = shortenFile.text
  if (text.contains('allowAnalysisFromWriteActionInEdt(file) {')) {
    text = text.replace(
      'allowAnalysisFromWriteActionInEdt(file) {\n    collectPossibleReferenceShortenings(file, selection, shortenOptions, classShortenStrategy, callableShortenStrategy)\n}.invokeShortening()',
      'analyze(file) {\n    collectPossibleReferenceShortenings(file, selection, shortenOptions, classShortenStrategy, callableShortenStrategy)\n}.invokeShortening()'
    )
    if (!text.contains('import org.jetbrains.kotlin.analysis.api.analyze')) {
      text = text.replace('import com.intellij.psi.createSmartPointer\n',
                          'import com.intellij.psi.createSmartPointer\nimport org.jetbrains.kotlin.analysis.api.analyze\n')
    }
    shortenFile.text = text
    log.info("Patched shortenUtils.kt: replaced allowAnalysisFromWriteActionInEdt with analyze")
  }
}

// 2. base/psi/KotlinPsiUtils.kt: remove ImplementationDetailClassNameCheckerProvider
//    (IDE extension point from base/psi/extensions, not available standalone).
//    Replace presentableClassId with a simple delegation to classIdIfNonLocal.
def basePsiUtils = new File(srcDir, 'org/jetbrains/kotlin/idea/base/psi/KotlinPsiUtils.kt')
if (basePsiUtils.exists()) {
  def text = basePsiUtils.text
  text = text.replace('import org.jetbrains.kotlin.idea.base.psi.extensions.ImplementationDetailClassNameCheckerProvider\n', '')
  text = text.replace(
    '''val KtClassOrObject.presentableClassId: ClassId?
    get() {
        if (KtPsiUtil.isLocal(this)) return null
        val packageName = containingKtFile.packageFqName
        val checker = ImplementationDetailClassNameCheckerProvider.get(this)
        val classNames = buildList {
            for (clazz in parentsOfType<KtDeclaration>()) {
                val className = clazz.name
                when {
                    className == null -> return null
                    checker.isImplementationDetail(className) -> continue
                    else -> add(className)
                }
            }
        }
        return ClassId(
            packageFqName = packageName,
            relativeClassName = FqName(classNames.asReversed().joinToString(separator = ".")),
            isLocal = false
        )
    }''',
    'val KtClassOrObject.presentableClassId: ClassId?\n    get() = classIdIfNonLocal'
  )
  basePsiUtils.text = text
  log.info("Patched base/psi/KotlinPsiUtils.kt: simplified presentableClassId")
}

// 3. ConvertToBlockBodyUtils.kt: setTypeReference() now takes KtTypeReference?, not String.
def convertUtils = new File(srcDir, 'org/jetbrains/kotlin/idea/codeinsight/utils/ConvertToBlockBodyUtils.kt')
if (convertUtils.exists()) {
  def text = convertUtils.text
  // In the KtNamedFunction branch, this.project is in scope via smart-cast.
  text = text.replace(
    '                    setTypeReference(context.returnTypeString)',
    '                    setTypeReference(KtPsiFactory(project).createType(context.returnTypeString))'
  )
  // In the KtPropertyAccessor branch, parent is KtProperty.
  text = text.replace(
    '                    parent.setTypeReference(context.returnTypeString)',
    '                    parent.setTypeReference(KtPsiFactory(parent.project).createType(context.returnTypeString))'
  )
  convertUtils.text = text
  log.info("Patched ConvertToBlockBodyUtils.kt: wrapped String in KtPsiFactory.createType() for setTypeReference")
}

// 4. CodeInliner.kt: ExpectActualUtils (IDE-level, not on classpath) used only in getDefaultValue.
//    Remove the imports and simplify getDefaultValue to return parameter.defaultValue directly.
def codeInliner = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/inline/codeInliner/CodeInliner.kt')
if (codeInliner.exists()) {
  def text = codeInliner.text
  text = text.replace('import org.jetbrains.kotlin.idea.search.ExpectActualUtils.actualsForExpect\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.search.ExpectActualUtils.expectDeclarationIfAny\n', '')
  text = text.replace(
    '''    private fun getDefaultValue(parameter: KtParameter): KtExpression? {
        val ownerFunction = parameter.ownerFunction
        val defaultValueFromExpect = ownerFunction
            ?.expectDeclarationIfAny()
            ?.takeIf { it != ownerFunction }
            ?.valueParameters()
            ?.get(parameter.parameterIndex())
            ?.defaultValue
        return defaultValueFromExpect ?: parameter.defaultValue
    }''',
    '''    private fun getDefaultValue(parameter: KtParameter): KtExpression? = parameter.defaultValue'''
  )
  codeInliner.text = text
  log.info("Patched CodeInliner.kt: removed ExpectActualUtils, simplified getDefaultValue")
}

// 5. ClassUsageReplacementStrategy.kt: j2k.resolve extension (K1-only, not on classpath).
//    Replace with standard PSI mainReference.resolve().
def classUsage = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/inline/codeInliner/ClassUsageReplacementStrategy.kt')
if (classUsage.exists()) {
  def text = classUsage.text
  text = text.replace('import org.jetbrains.kotlin.j2k.resolve\n', '')
  // referenceExpression?.resolve() → referenceExpression?.mainReference?.resolve()
  text = text.replace('referenceExpression?.resolve()?.kotlinFqName', 'referenceExpression?.mainReference?.resolve()?.kotlinFqName')
  // referenceExpression.resolve() as? KtClassOrObject
  text = text.replace('referenceExpression.resolve() as? KtClassOrObject', 'referenceExpression.mainReference?.resolve() as? KtClassOrObject')
  classUsage.text = text
  log.info("Patched ClassUsageReplacementStrategy.kt: replaced j2k.resolve with mainReference.resolve()")
}

// 6. UsageReplacementStrategy.kt: replaceUsagesInWholeProject uses IDE-only APIs
//    (runWithModalProgressBlocking, KotlinSourceFilterScope, executeWriteCommand).
//    Remove the function entirely — only replaceUsages() is needed at runtime.
def usageReplacementStrategy = new File(srcDir, 'org/jetbrains/kotlin/idea/refactoring/inline/codeInliner/UsageReplacementStrategy.kt')
if (usageReplacementStrategy.exists()) {
  def text = usageReplacementStrategy.text
  text = text.replace('import com.intellij.platform.ide.progress.runWithModalProgressBlocking\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.base.projectStructure.scope.KotlinSourceFilterScope\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.util.application.executeWriteCommand\n', '')
  def startMarker = '\nfun UsageReplacementStrategy.replaceUsagesInWholeProject('
  def endMarker   = '\nfun UsageReplacementStrategy.replaceUsages('
  def startIdx = text.indexOf(startMarker)
  def endIdx   = text.indexOf(endMarker)
  if (startIdx >= 0 && endIdx >= 0) {
    text = text.substring(0, startIdx) + '\n' + text.substring(endIdx)
  }
  usageReplacementStrategy.text = text
  log.info("Patched UsageReplacementStrategy.kt: removed replaceUsagesInWholeProject and IDE imports")
}

// 7. InlinePostProcessor.kt: canMoveLambdaOutsideParentheses is in the k2 package (not common refactoring).
def inlinePostProcessor = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/inline/codeInliner/InlinePostProcessor.kt')
if (inlinePostProcessor.exists()) {
  def text = inlinePostProcessor.text
  text = text.replace(
    'import org.jetbrains.kotlin.idea.refactoring.canMoveLambdaOutsideParentheses',
    'import org.jetbrains.kotlin.idea.k2.refactoring.canMoveLambdaOutsideParentheses'
  )
  inlinePostProcessor.text = text
  log.info("Patched InlinePostProcessor.kt: fixed canMoveLambdaOutsideParentheses import to k2 package")
}

// 8. InlinePreprocessorUtil.kt: getKaModule is IDE-only project-structure API.
//    Replace isImportable() with a lightweight PSI-only check (avoids analyze(KaModule)).
def inlinePreprocessorUtil = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/inline/codeInliner/InlinePreprocessorUtil.kt')
if (inlinePreprocessorUtil.exists()) {
  def text = inlinePreprocessorUtil.text
  text = text.replace('import org.jetbrains.kotlin.idea.base.projectStructure.getKaModule\n', '')
  def oldIsImportable = '''        fun isImportable(t: PsiElement): Boolean {
            val module = t.getKaModule(t.project, useSiteModule = null)
            return analyze(module) {
                val resolvedSymbol = when (t) {
                    is KtNamedDeclaration -> t.symbol
                    is PsiMember -> {
                        if ((t.containingFile as? PsiJavaFile)?.packageName == CommonClassNames.DEFAULT_PACKAGE) {
                            return@analyze false
                        }
                        if (t is PsiClass) {
                            return@analyze t.qualifiedName != null
                        }
                        t.callableSymbol
                    }
                    else -> null
                } ?: return@analyze false
                if (resolvedSymbol is KaEnumEntrySymbol || resolvedSymbol is KaClassSymbol && resolvedSymbol.containingSymbol is KaClassSymbol) {
                    return@analyze false
                }
                val containingSymbol = resolvedSymbol.containingDeclaration ?: return@analyze true
                if (containingSymbol is KaDeclarationContainerSymbol) {
                    val staticScope = containingSymbol.staticMemberScope
                    return@analyze resolvedSymbol in staticScope.declarations
                }
                return@analyze false
            }
        }'''
  def newIsImportable = '''        fun isImportable(t: PsiElement): Boolean {
            return when (t) {
                is KtNamedDeclaration -> {
                    if (KtPsiUtil.isLocal(t)) return false
                    t.fqName != null
                }
                is PsiMember -> {
                    if ((t.containingFile as? PsiJavaFile)?.packageName == CommonClassNames.DEFAULT_PACKAGE) return false
                    if (t is PsiClass) return t.qualifiedName != null
                    t.containingClass?.qualifiedName != null
                }
                else -> false
            }
        }'''
  text = text.replace(oldIsImportable, newIsImportable)
  inlinePreprocessorUtil.text = text
  log.info("Patched InlinePreprocessorUtil.kt: removed getKaModule, simplified isImportable")
}

// 9. ContextReceiversUtil.kt: KotlinParameterInfo is from the changeSignature subpackage (not compiled).
//    Remove createReplacementReceiverArgumentExpression and its import.
def contextReceiversUtil = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/util/ContextReceiversUtil.kt')
if (contextReceiversUtil.exists()) {
  def text = contextReceiversUtil.text
  text = text.replace('import org.jetbrains.kotlin.idea.k2.refactoring.changeSignature.KotlinParameterInfo\n', '')
  def funcMarker = '\ninternal fun createReplacementReceiverArgumentExpression('
  def funcIdx = text.indexOf(funcMarker)
  if (funcIdx >= 0) {
    text = text.substring(0, funcIdx) + '\n'
  }
  contextReceiversUtil.text = text
  log.info("Patched ContextReceiversUtil.kt: removed KotlinParameterInfo import and createReplacementReceiverArgumentExpression")
}

// 10. ExtractionData.kt: substringContextOrThis, ExtractableSubstringInfo, extractableSubstringInfo
//     are in base/analysis which is K1-only. In NB we never extract string-template substrings,
//     so stub physicalElements to use identity and substringInfo to return null.
def extractionData = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/extractFunction/ExtractionData.kt')
if (extractionData.exists()) {
  def text = extractionData.text
  text = text.replace('import org.jetbrains.kotlin.idea.refactoring.introduce.ExtractableSubstringInfo\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.refactoring.introduce.extractableSubstringInfo\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.refactoring.introduce.substringContextOrThis\n', '')
  text = text.replace(
    'override val physicalElements: List<PsiElement> = originalElements.map { it.substringContextOrThis }',
    'override val physicalElements: List<PsiElement> = originalElements'
  )
  text = text.replace(
    '''override val substringInfo: ExtractableSubstringInfo?
        get() = (originalElements.singleOrNull() as? KtExpression)?.extractableSubstringInfo''',
    'override val substringInfo: Nothing? get() = null'
  )
  extractionData.text = text
  log.info("Patched ExtractionData.kt: stubbed substringContextOrThis and extractableSubstringInfo")
}

// 11. parametersUtil.kt: BuiltinTypes from org.jetbrains.kotlin.fir is not on the classpath.
//     The import is unused — remove it.
def parametersUtil = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/extractFunction/parametersUtil.kt')
if (parametersUtil.exists()) {
  def text = parametersUtil.text
  text = text.replace('import org.jetbrains.kotlin.fir.BuiltinTypes\n', '')
  parametersUtil.text = text
  log.info("Patched parametersUtil.kt: removed unused BuiltinTypes import")
}

// 13. ExtractableCodeDescriptor.kt: duplicates property calls findDuplicates() from
//     extractDuplicatesUtil.kt which imports IDE-heavy duplicateUtil.kt (Editor, Messages, etc.).
//     Stub duplicates to emptyList() — NB does not use the duplicate-replacement UI.
def extractableDescriptor = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/extractFunction/ExtractableCodeDescriptor.kt')
if (extractableDescriptor.exists()) {
  def text = extractableDescriptor.text
  text = text.replace(
    'override val duplicates: List<DuplicateInfo<KaType>> by lazy { findDuplicates() }',
    'override val duplicates: List<DuplicateInfo<KaType>> by lazy { emptyList() }'
  )
  extractableDescriptor.text = text
  log.info("Patched ExtractableCodeDescriptor.kt: stubbed duplicates to emptyList()")
}

// 14. K2MoveRenameUsageInfo.kt: the IDEA Copy Declaration retargeting engine (E9.19).
//     Three adaptations for standalone use:
//       a. Drop the Java-reference `Light` path and the external-usage helpers
//          (find/findExternalUsages/preProcessUsages). They pull in platform move handlers
//          (MoveClassHandler/MoveMemberHandler/MoveMembersProcessor) and asJava light classes
//          that are not on the standalone classpath. Copy Declaration only uses markInternalUsages
//          + retargetUsages (internal, from-copy), so these paths are never invoked.
//       b. allowAnalysisFromWriteActionInEdt was removed in analysis-api 2.3.21 — swap for analyze {}
//          (same as patch #1 for shortenUtils.kt).
//       c. ProgressManager.getInstance().progressIndicator is null in the standalone container —
//          fall back to an EmptyProgressIndicator so pushState()/text/fraction are no-ops.
def k2MoveUsage = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/move/processor/usages/K2MoveRenameUsageInfo.kt')
if (k2MoveUsage.exists()) {
  def text = k2MoveUsage.text

  // a. Remove imports that only the dropped paths use and that do not resolve standalone.
  ['import com.intellij.psi.search.searches.ReferencesSearch\n',
   'import com.intellij.refactoring.move.moveClassesOrPackages.MoveClassHandler\n',
   'import com.intellij.refactoring.move.moveMembers.MoveMemberHandler\n',
   'import com.intellij.refactoring.move.moveMembers.MoveMembersOptions\n',
   'import com.intellij.refactoring.move.moveMembers.MoveMembersProcessor\n',
   'import org.jetbrains.kotlin.asJava.toLightElements\n',
   'import org.jetbrains.kotlin.idea.base.util.projectScope\n',
   'import org.jetbrains.kotlin.idea.base.analysis.api.utils.allowAnalysisFromWriteActionInEdt\n'
  ].each { imp -> text = text.replace(imp, '') }

  // Remove the `Light` nested class (its foreign-language reference handling).
  def lightStart = text.indexOf('    /**\n     * A usage described in a foreign language like Java or Groovy.\n     */\n    class Light(')
  def lightEnd   = text.indexOf('    /**\n     * A Kotlin usage, Kotlin usages can either be internal and external.')
  if (lightStart >= 0 && lightEnd > lightStart) {
    text = text.substring(0, lightStart) + text.substring(lightEnd)
  }

  // Remove find() + preProcessUsages() (external-usage entry points, unused by Copy Declaration).
  def findStart = text.indexOf('        fun find(declaration: KtNamedDeclaration): List<UsageInfo> {')
  def findEnd   = text.indexOf('        /**\n         * Used to store usage info for an internal reference so that after the move')
  if (findStart >= 0 && findEnd > findStart) {
    text = text.substring(0, findStart) + text.substring(findEnd)
  }

  // Remove findExternalUsages() (constructs Light, uses ReferencesSearch/projectScope/toLightElements).
  def extStart = text.indexOf('        /**\n         * Finds usages to [declaration] excluding the usages inside [declaration].')
  def extEnd   = text.indexOf('        private fun Map<PsiFile, Map<PsiElement, PsiNamedElement>>.mergedWith(')
  if (extStart >= 0 && extEnd > extStart) {
    text = text.substring(0, extStart) + text.substring(extEnd)
  }

  // b. allowAnalysisFromWriteActionInEdt(x) { } → analyze(x) { }
  text = text.replace('allowAnalysisFromWriteActionInEdt(', 'analyze(')
  if (!text.contains('import org.jetbrains.kotlin.analysis.api.analyze\n')) {
    text = text.replace('import org.jetbrains.kotlin.analysis.api.KaSession\n',
                        'import org.jetbrains.kotlin.analysis.api.KaSession\nimport org.jetbrains.kotlin.analysis.api.analyze\n')
  }

  // c. Null-safe the standalone progress indicator.
  text = text.replace('ProgressManager.getInstance().progressIndicator',
                      '(ProgressManager.getInstance().progressIndicator ?: com.intellij.openapi.progress.EmptyProgressIndicator())')

  // d. markInternalUsageInfo calls expr.mainReference on every KtReferenceExpression. The local
  //    mainReference stub (KotlinRefactoring) types KtReferenceExpression.mainReference as a
  //    non-null KtSimpleNameReference via .first(); for a KtCallExpression the reference list has
  //    no simple-name reference in standalone (no invoke-reference contributor), so .first() throws.
  //    Make this one call site null-safe: a call expression with no reference is skipped, exactly
  //    like IDEA's net effect (its callee simple name is processed separately and carries the import).
  text = text.replace('            val mainReference = expr.mainReference\n',
                      '            val mainReference = expr.references.filterIsInstance<KtReference>().firstOrNull() ?: return\n')

  k2MoveUsage.text = text
  log.info("Patched K2MoveRenameUsageInfo.kt: dropped Light/external paths, analyze swap, null-safe progress")
}

// 15. K2ReferenceMutateService is `internal`; make it public so the Nbm session can register it
//     as the application-level KtReferenceMutateService implementation.
def k2RefMutate = new File(srcDir, 'org/jetbrains/kotlin/idea/k2/refactoring/K2ReferenceMutateService.kt')
if (k2RefMutate.exists()) {
  def text = k2RefMutate.text
  text = text.replace('internal class K2ReferenceMutateService', 'class K2ReferenceMutateService')
  k2RefMutate.text = text
  log.info("Patched K2ReferenceMutateService.kt: made class public for service registration")
}
